// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: give the contract some ether
        vm.deal(address(c), 10 ether);
        // A non-owner address
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        // Attempt to withdraw as non-owner
        bool ok;
        vm.prank(attacker);
        try c.withdrawAll(address(this)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference (correct) contract, it reverts -> ok false.
        // In buggy contract, it succeeds and transfers balance -> ok true.
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether via owner
        vm.deal(address(this), 1 ether);
        payable(address(c)).transfer(1 ether);

        // Non-owner tries to withdraw
        address nonOwner = address(0x1234);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll(nonOwner) { ok = true; } catch { ok = false; }

        // The reference should revert (ok == false), meaning balance unchanged; buggy version would succeed and transfer
        assertTrue(!ok && address(c).balance == balanceBefore);
    }
}
